=== FILE: credit_counter_props.sv ===
// Formal properties for credit_counter, written from interface_spec.md.
// Immediate assertions only (open Yosys front end); every $past is guarded
// by f_past_valid; one assertion per rule; covers for each scenario.
`default_nettype none
module credit_counter_props #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    localparam [7:0] F_MAX = MAX;

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Environment: the only assumption. Reset is applied at the first edge
    // (spec 3.1); take and give are unconstrained.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // [req:CC-RANGE] credits never above MAX once reset has been applied.
    always @(*)
        if (f_past_valid)
            assert(credits <= F_MAX);

    // [req:CC-STATUS] avail and full follow credits combinationally.
    always @(*)
        assert(avail == (credits != 8'd0));
    always @(*)
        assert(full == (credits == F_MAX));

    always @(posedge clk) begin
        // [req:CC-RESET] reset loads MAX
        if (f_past_valid && !$past(rst_n))
            assert(credits == F_MAX);
        // [req:CC-RESET] reset clears err
        if (f_past_valid && !$past(rst_n))
            assert(!err);

        // [req:CC-TAKE] take only, credit available: down by one
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) != 8'd0))
            assert(credits == $past(credits) - 8'd1);

        // [req:CC-GIVE] give only, room available: up by one
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) < F_MAX))
            assert(credits == $past(credits) + 8'd1);

        // [req:CC-BOTH] take and give together: credits unchanged
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give))
            assert(credits == $past(credits));
        // [req:CC-BOTH] take and give together: nothing refused
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give)
                && !$past(err))
            assert(!err);

        // [req:CC-IDLE] neither: credits unchanged
        if (f_past_valid && $past(rst_n) && !$past(take) && !$past(give))
            assert(credits == $past(credits));

        // [req:CC-UNDERFLOW] take only at zero: credits stays zero
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) == 8'd0))
            assert(credits == 8'd0);
        // [req:CC-UNDERFLOW] take only at zero: err set
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give)
                && ($past(credits) == 8'd0))
            assert(err);

        // [req:CC-OVERFLOW] give only at MAX: credits stays MAX
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) == F_MAX))
            assert(credits == F_MAX);
        // [req:CC-OVERFLOW] give only at MAX: err set
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take)
                && ($past(credits) == F_MAX))
            assert(err);

        // [req:CC-ERR-STICKY] err stays set until reset
        if (f_past_valid && $past(rst_n) && $past(err))
            assert(err);

        // err port: err rises only on a refused take or give
        if (f_past_valid && $past(rst_n) && !$past(err)
                && !($past(take) && !$past(give) && ($past(credits) == 8'd0))
                && !($past(give) && !$past(take) && ($past(credits) == F_MAX)))
            assert(!err);
    end

    // Covers: scenarios the proof must still allow (vacuity check).
    always @(posedge clk) begin
        // empty reached by takes
        cover(f_past_valid && rst_n && (credits == 8'd0));
        // refilled to full by a give
        cover(f_past_valid && $past(rst_n) && $past(give) && !$past(take)
              && ($past(credits) != F_MAX) && (credits == F_MAX));
        // refused take (underflow) sets err
        cover(f_past_valid && $past(rst_n) && $past(take) && !$past(give)
              && ($past(credits) == 8'd0) && err);
        // refused give (overflow) sets err
        cover(f_past_valid && $past(rst_n) && $past(give) && !$past(take)
              && ($past(credits) == F_MAX) && err);
        // take and give together at zero
        cover(f_past_valid && $past(rst_n) && $past(take) && $past(give)
              && ($past(credits) == 8'd0) && !$past(err));
        // take and give together at MAX
        cover(f_past_valid && $past(rst_n) && $past(take) && $past(give)
              && ($past(credits) == F_MAX) && !$past(err));
        // err held while a later take succeeds
        cover(f_past_valid && $past(rst_n) && $past(err) && $past(take)
              && !$past(give) && ($past(credits) != 8'd0) && err);
        // reset clears a set err
        cover(f_past_valid && !$past(rst_n) && $past(err) && !err);
    end
endmodule

module credit_counter_formal (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    // [req:CC-PARAM] sample: MAX = 1 (zero and full adjacent),
    // 3 (not a power of two), 4 (default).
    credit_counter_props #(.MAX(1)) p_max1 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
    credit_counter_props #(.MAX(3)) p_max3 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
    credit_counter_props #(.MAX(4)) p_max4 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
endmodule
`default_nettype wire
=== END FILE ===
